$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1){flash('danger','Invalid department ID.');redirect('new_DepartmentAdmin.php');}$row=$departmentModel->find($id);if(!$row){flash('danger','Department not found.');redirect('new_DepartmentAdmin.php');}$errors=[];$data=$row;
if($_SERVER['REQUEST_METHOD']==='POST'){$data=array_merge($data,$_POST);$rid=filter_var($_POST['rid']??null,FILTER_VALIDATE_INT);$brid=filter_var($_POST['brid']??null,FILTER_VALIDATE_INT);$name=trim((string)($_POST['departmentname']??''));$floors=trim((string)($_POST['floors']??''));$desc=trim((string)($_POST['descriptionOfDepartment']??''));if(!verify_csrf($_POST['csrf_token']??null))$errors[]='Invalid form token.';if($rid===false||$rid===null||$rid<1||!$roomModel->exists($rid))$errors[]='Room ID is invalid or does not exist.';if($brid===false||$brid===null||$brid<1||!$buildingModel->exists($brid))$errors[]='Building ID is invalid or does not exist.';if($name==='')$errors[]='Department name is required.';if($floors==='')$errors[]='Floor information is required.';if(!$errors){$newImage=null;try{$newImage=image_upload();$departmentModel->update($id,$rid,$brid,$name,$floors,$desc,$newImage);if($newImage)delete_uploaded_image((string)$row['imgdepartment']);flash('success','Department updated successfully.');redirect('new_DepartmentAdmin.php');}catch(Throwable $e){error_log($e->getMessage());if($newImage)delete_uploaded_image($newImage);$errors[]='The department could not be updated.';}}}
